function makePickups(){const spots=[[-38,-43],[18,-54],[54,-28]];spots.forEach((p,i)=>{const y=terrainHeight(...p);const g=new THREE.Group();g.position.set(p[0],y+.7,p[1]);scene.add(g);const shard=mesh(new THREE.OctahedronGeometry(.48,.1),new THREE.MeshStandardMaterial({color:0xff9b4a,emissive:0xb8480d,emissiveIntensity:1.6,metalness:.25,roughness:.24}),g);shard.scale.set(.65,1.5,.65);const ring=mesh(new THREE.TorusGeometry(.68,.035,6,24),new THREE.MeshBasicMaterial({color:0xffc478}));ring.rotation.x=Math.PI/2;g.add(ring);const light=new THREE.PointLight(0xff8033,.8,7);g.add(light);g.userData={type:'shard',index:i,active:true};pickups.push(g)})}
function makeEnemy(x,z,type='wolf'){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);scene.add(g);const wolf=type==='wolf',fur=wolf?0x51483b:0x706448;const body=mesh(new THREE.SphereGeometry(wolf?.55:.45,12,10),mat(fur),g);body.position.y=wolf?.75:.78;body.scale.set(1.35,.8,.8);const head=mesh(new THREE.SphereGeometry(wolf?.32:.27,10,8),mat(wolf?0x625746:0x807556),g);head.position.set(0,1.02,.58);if(wolf){for(const x of [-.16,.16]){const eye=mesh(new THREE.SphereGeometry(.055,8,6),new THREE.MeshBasicMaterial({color:0xffa043}),g);eye.position.set(x,1.09,.84)}for(let i=0;i<4;i++){const leg=mesh(new THREE.CylinderGeometry(.075,.1,.42,6),mat(fur),g);leg.position.set(i<2?-.32:.32,.35,i%2?-.26:.35)}}else{const horn=mesh(new THREE.ConeGeometry(.1,.45,6),mat(0xc5b99d),g);horn.position.set(-.2,1.35,.52);horn.rotation.x=-.5}g.userData={type,hp:wolf?45:65,maxHp:wolf?45:65,aggro:false,attack:0,alive:true,home:new THREE.Vector3(x,0,z),phase:Math.random()*5};enemies.push(g);return g}
function makeEnemies(){makeEnemy(17,-4,'wolf');makeEnemy(34,-39,'wolf');makeEnemy(58,-52,'wisp');makeEnemy(-43,-32,'wolf');}
function setupUI(){function choices(id,key){$$('#'+id+' .choice').forEach(el=>el.addEventListener('click',()=>{$$('#'+id+' .choice').forEach(x=>x.classList.remove('active'));el.classList.add('active');state[key]=el.dataset.value}))}choices('races','race');choices('classes','path');$('#begin').onclick=()=>{state.name=$('#heroName').value.trim()||'Wanderer';$('#creator').style.display='none';$('#hud').style.display='block';makePlayer();$('#hudName').textContent=state.name.toUpperCase();if(state.path==='Spellblade'){state.maxMana=90;state.mana=90}else if(state.path==='Ranger'){state.maxStamina=120;state.stamina=120}showToast(`The vale remembers you, ${state.name}.`,'Your journey begins at Hearthstead.');saveGame();};$$('.icon-btn').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));$('#closeModal').onclick=closePanel;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closePanel()});$('#dialogueNext').onclick=continueDialogue;document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame()});$$('[data-move]').forEach(b=>{const k=b.dataset.move;const map={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'};b.addEventListener('pointerdown',e=>{e.preventDefault();keys[map[k]]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[map[k]]=false))});$$('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();if(b.dataset.action==='attack')attack();if(b.dataset.action==='spell')castSpell();if(b.dataset.action==='interact')interact()}));loadGame()}
function onKeyDown(e){if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyF'||e.code==='KeyE')interact();if(e.code==='KeyQ')castSpell();if(e.code==='Space')dodge();if(e.code==='Escape'){if($('#modal').classList.contains('open'))closePanel();else openPanel('pause')}if(e.code==='KeyM')openPanel('map');if(e.code==='KeyJ')openPanel('journal');if(e.code==='KeyC')openPanel('character')}
function onPointerDown(e){if(e.button===0){mouseDown=true;lastPointer={x:e.clientX,y:e.clientY};if($('#hud').style.display==='block'&&!$('#modal').classList.contains('open')&&!talking)attack()}if(e.button===2)e.preventDefault()}
function onPointerMove(e){if(mouseDown&&e.buttons===1&&$('#hud').style.display==='block'){const dx=e.clientX-lastPointer.x;state.yaw-=dx*.004;lastPointer={x:e.clientX,y:e.clientY}}}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}
function showToast(title,sub=''){const el=$('#toast');el.innerHTML=title+(sub?`<span>${sub}</span>`:'');el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3100)}
function updateBars(){for(const [id,val,max] of [['health',state.health,state.maxHealth],['stamina',state.stamina,state.maxStamina],['mana',state.mana,state.maxMana]]){$('#'+id+'Fill').style.width=Math.max(0,val/max*100)+'%';$('#'+id+'Text').textContent=`${Math.ceil(val)} / ${max}`}$('#levelNum').textContent=state.level;$('#xpFill').style.width=state.xp/state.nextXp*100+'%';$('#xpText').textContent=`${state.xp} / ${state.nextXp} XP`}
function xp(n){state.xp+=n;while(state.xp>=state.nextXp){state.xp-=state.nextXp;state.level++;state.nextXp=Math.floor(state.nextXp*1.35);state.maxHealth+=12;state.health=state.maxHealth;state.maxMana+=6;state.mana=state.maxMana;state.perk++;showToast(`LEVEL ${state.level}`,'You feel stronger. Choose a perk in Character.')}updateBars();saveGame()}
function saveGame(){try{const data={...state,position:{x:state.position.x,y:state.position.y,z:state.position.z},flags:state.flags};localStorage.setItem('ashenv ale-save'.replace(' ',''),JSON.stringify(data))}catch(e){}}
function loadGame(){try{const raw=localStorage.getItem('ashenvale-save');if(!raw)return;const s=JSON.parse(raw);if(s.name){Object.assign(state,s);state.position=new THREE.Vector3(s.position.x,s.position.y,s.position.z);if(s.path==='Spellblade'){state.maxMana=Math.max(90,state.maxMana)}$('#heroName').value=state.name;$('#races .choice').forEach(x=>x.classList.toggle('active',x.dataset.value===state.race));$('#classes .choice').forEach(x=>x.classList.toggle('active',x.dataset.value===state.path));$('#hudName').textContent=state.name.toUpperCase();if(state.path==='Spellblade')state.mana=Math.min(state.mana,90);updateQuest();updateBars()}}catch(e){}}
function updateQuest(){if(state.quest===0){$('#questTitle').textContent='Ashes of the Old Road';$('#questDesc').textContent=state.keeperMet?'A waystone burns beyond the old road.':'Speak with the keeper at Hearthstead.';$('#objective').textContent=state.keeperMet?`◦ Find the Ember Shard (${state.embers} / 3)`:'◦ Find the village keeper'}else if(state.quest===1){$('#questTitle').textContent='The Ember Shards';$('#questDesc').textContent='Recover the three sparks scattered beyond the village.';$('#objective').textContent=`◦ Gather Ember Shards (${state.embers} / 3)`}else{$('#questTitle').textContent='A Flame Rekindled';$('#questDesc').textContent='The old waystone answers your touch.';$('#objective').textContent='✓ The first ember is yours'}}
function closePanel(){ $('#modal').classList.remove('open');activePanel='';keys.Escape=false}
function openPanel(which){if(talking)return;activePanel=which;$('#modal').classList.add('open');const title={character:'Character',journal:'Journal',map:'The Vale',pause:'The Journey'}[which]||'Journal';$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=which==='pause'?'Take a breath':'Wanderer’s record';let html='';if(which==='character'){html=`<div class="tab-row"><div class="tab active">OVERVIEW</div><div class="tab">ABILITIES</div></div><div class="statgrid"><div class="stat"><b>${state.name}</b><span>${state.race} · ${state.path}</span></div><div class="stat"><b>Level ${state.level}</b><span>${state.xp} / ${state.nextXp} experience</span></div><div class="stat"><b>✦ ${state.embers} / 3</b><span>Ember shards found</span></div><div class="stat"><b>⚔ ${state.kills}</b><span>Hostile creatures defeated</span></div></div><h3 style="font:500 14px Cinzel;color:#e4d3ad;margin:20px 0 7px">Path talents · ${state.perk} point${state.perk===1?'':'s'} available</h3>${perkHtml('Iron Resolve','Increase maximum health by 20.','health')}${perkHtml('Deep Wellspring','Increase maximum magicka by 15.','mana')}${perkHtml('Fleetfoot','Increase maximum stamina by 20.','stamina')}<h3 style="font:500 14px Cinzel;color:#e4d3ad;margin:18px 0 7px">Pack</h3><div class="modal-body">${state.inventory.map(x=>'◦ '+x).join('<br>')}</div>`}else if(which==='journal'){html=`<div class="tab-row"><div class="tab active">QUESTS</div><div class="tab">LORE</div></div><h3 style="font:500 15px Cinzel;color:#e4d3ad">${$('#questTitle').textContent}</h3><p>${$('#questDesc').textContent}</p><p style="color:#e6c47b">${$('#objective').textContent}</p><hr style="border-color:#ffffff20"><p style="color:#9ba79a;font-size:11px">The last warm wind has left the mountains. Hearthstead’s keeper has watched the old road for longer than anyone can remember. Find them, and learn what still burns beneath the snow.</p><h3 style="font:500 15px Cinzel;color:#e4d3ad;margin-top:20px">Controls</h3><p>WASD move · Mouse drag turn · Left click strike · Q ember bolt · Space dodge · F interact · M map · C character</p>`}else if(which==='map'){html=`<div class="map-wrap"><canvas id="mapCanvas" width="900" height="470"></canvas></div><div class="map-legend">✦ You &nbsp;&nbsp; ● Hearthstead &nbsp;&nbsp; ◇ Ember shard &nbsp;&nbsp; ⌂ Waystone ruins</div>`}else{html=`<p>Rest a moment, wanderer. The vale will wait.</p><div class="perk"><span>Continue your journey</span><button id="resume">RETURN</button></div><div class="perk"><span>Start over with a new wanderer</span><button id="newGame">NEW GAME</button></div><div class="perk"><span>Save is stored on this device</span><button id="saveNow">SAVE</button></div>`}$('#modalContent').innerHTML=html;if(which==='map')drawMap();if(which==='character')$$('[data-perk]').forEach(b=>b.onclick=()=>buyPerk(b.dataset.perk));if(which==='pause'){$('#resume').onclick=closePanel;$('#saveNow').onclick=()=>{saveGame();showToast('Journey saved.')};$('#newGame').onclick=()=>{localStorage.removeItem('ashenvale-save');location.reload()}}}
function perkHtml(title,desc,key){return `<div class="perk"><span><b style="display:block;color:#e7dfca;font:500 11px Cinzel">${title}</b><small style="font-size:10px;color:#99a398">${desc}</small></span><button data-perk="${key}" ${state.perk<1?'disabled style="opacity:.4"':''}>${state.perk>0?'LEARN':'LOCKED'}</button></div>`}
function buyPerk(key){if(state.perk<1)return;state.perk--;if(key==='health'){state.maxHealth+=20;state.health+=20}else if(key==='mana'){state.maxMana+=15;state.mana+=15}else{state.maxStamina+=20;state.stamina+=20}updateBars();saveGame();openPanel('character');showToast('Talent learned.')}
function drawMap(){const c=$('#mapCanvas');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle='#192b27';ctx.fillRect(0,0,w,h);for(let i=0;i<130;i++){const x=(i*173)%w,y=(i*311)%h;ctx.fillStyle=i%3===0?'#36483a':'#263a32';ctx.beginPath();ctx.arc(x,y,5+(i%13),0,Math.PI*2);ctx.fill()}ctx.strokeStyle='#75805d';ctx.lineWidth=28;ctx.beginPath();ctx.moveTo(0,h*.72);ctx.bezierCurveTo(w*.25,h*.62,w*.35,h*.34,w*.52,h*.45);ctx.bezierCurveTo(w*.7,h*.57,w*.81,h*.3,w,h*.36);ctx.stroke();ctx.strokeStyle='#50818a';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(w*.82,0);ctx.bezierCurveTo(w*.71,h*.32,w*.92,h*.64,w*.78,h);ctx.stroke();function dot(x,y,color,r,label){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.font='18px sans-serif';ctx.fillStyle='#e7e2ca';ctx.fillText(label,x+11,y+5)}dot(w*.39,h*.58,'#e1ba6d',8,'Hearthstead');dot(w*.72,h*.33,'#b3a17a',7,'Old ruins');pickups.forEach(p=>{if(p.userData.active)dot(w*(.5+p.position.x/230),h*(.5+p.position.z/230),'#ef914e',5,'')});dot(w*(.5+state.position.x/230),h*(.5+state.position.z/230),'#ffdf89',7,'▲')}

